create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,name text not null default '',university text not null default '',degree text not null default '',specialization text not null default '',academic_year text not null default '',skills text not null default '',interests text not null default '',goals text not null default '',bio text not null default '',portfolio text not null default '',avatar text not null default '',preferences jsonb not null default '{}');
grant select,insert,update on public.profiles to authenticated; grant all on public.profiles to service_role; alter table public.profiles enable row level security; create policy own_profiles on public.profiles for all to authenticated using(id=(select auth.uid())) with check(id=(select auth.uid()));
create table public.user_roles(user_id uuid references auth.users(id) on delete cascade, role text check(role in ('student','admin','educator','organizer','provider')),primary key(user_id,role));
grant select on public.user_roles to authenticated; grant all on public.user_roles to service_role; alter table public.user_roles enable row level security; create policy own_roles on public.user_roles for select to authenticated using(user_id=(select auth.uid()));
create function public.campus_role(r text) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.user_roles where user_id=auth.uid() and role=r) $$; revoke all on function public.campus_role(text) from public; grant execute on function public.campus_role(text) to authenticated;
create function public.campus_signup() returns trigger language plpgsql security definer set search_path='' as $$ begin insert into public.profiles(id,name) values(new.id,left(coalesce(new.raw_user_meta_data->>'name',new.raw_user_meta_data->>'full_name',''),120)); insert into public.user_roles values(new.id,'student'); return new; end $$; revoke all on function public.campus_signup() from public; create trigger campus_signup after insert on auth.users for each row execute function public.campus_signup();
create table public.events(id uuid primary key default gen_random_uuid(),owner uuid not null default auth.uid(),title text not null,category text not null,description text not null,venue text not null,starts_at timestamptz not null,deadline timestamptz not null,eligibility text not null,created_at timestamptz not null default now(),check(deadline<=starts_at));
grant select,insert,update on public.events to authenticated; grant all on public.events to service_role; alter table public.events enable row level security; create policy events_read on public.events for select to authenticated using(true); create policy publish_event on public.events for insert to authenticated with check(owner=(select auth.uid()) and (public.campus_role('organizer') or public.campus_role('educator') or public.campus_role('admin'))); create policy edit_event on public.events for update to authenticated using(owner=(select auth.uid()) and (public.campus_role('organizer') or public.campus_role('educator') or public.campus_role('admin'))) with check(owner=(select auth.uid()) and (public.campus_role('organizer') or public.campus_role('educator') or public.campus_role('admin')));
create table public.event_activity(user_id uuid not null default auth.uid(),event_id uuid references public.events(id) on delete cascade,kind text check(kind in ('saved','registered')),created_at timestamptz not null default now(),primary key(user_id,event_id,kind));
grant select,insert,delete on public.event_activity to authenticated; grant all on public.event_activity to service_role; alter table public.event_activity enable row level security; create policy activity_read on public.event_activity for select to authenticated using(user_id=(select auth.uid()) or (kind='registered' and exists(select 1 from public.events where id=event_id and owner=(select auth.uid())))); create policy activity_write on public.event_activity for insert to authenticated with check(user_id=(select auth.uid()) and (kind='saved' or exists(select 1 from public.events where id=event_id and deadline>=now()))); create policy activity_delete on public.event_activity for delete to authenticated using(user_id=(select auth.uid()));
create table public.announcements(id uuid primary key default gen_random_uuid(),owner uuid not null default auth.uid(),title text not null,body text not null,urgent boolean not null default false,created_at timestamptz not null default now());
grant select,insert on public.announcements to authenticated; grant all on public.announcements to service_role; alter table public.announcements enable row level security; create policy announcements_read on public.announcements for select to authenticated using(true); create policy announcements_write on public.announcements for insert to authenticated with check(owner=(select auth.uid()) and (public.campus_role('admin') or public.campus_role('educator')));
create table public.analyses(id uuid primary key default gen_random_uuid(),owner uuid not null default auth.uid(),title text not null,result text not null,created_at timestamptz not null default now());
grant select,insert,delete on public.analyses to authenticated; grant all on public.analyses to service_role; alter table public.analyses enable row level security; create policy analyses_own on public.analyses for all to authenticated using(owner=(select auth.uid())) with check(owner=(select auth.uid()));
create table public.complaints(id uuid primary key default gen_random_uuid(),owner uuid not null default auth.uid(),category text not null,location text not null,description text not null,priority text not null check(priority in ('Low','Normal','High','Urgent')),department text not null,anonymous boolean not null default false,photo text not null default '',status text not null default 'Submitted' check(status in ('Submitted','Under Review','Assigned','In Progress','Resolved')),resolution text not null default '',created_at timestamptz not null default now());
grant select,insert on public.complaints to authenticated; grant all on public.complaints to service_role; alter table public.complaints enable row level security; create policy complaint_read on public.complaints for select to authenticated using(owner=(select auth.uid())); create policy complaint_submit on public.complaints for insert to authenticated with check(owner=(select auth.uid()) and status='Submitted' and resolution='');
create table public.service_providers(user_id uuid primary key,department text not null);
grant select on public.service_providers to authenticated; grant all on public.service_providers to service_role; alter table public.service_providers enable row level security; create policy service_own on public.service_providers for select to authenticated using(user_id=(select auth.uid()));
create function public.campus_service_queue() returns table(id uuid,category text,location text,description text,priority text,department text,status text,resolution text,photo text,created_at timestamptz,reporter text) language sql stable security definer set search_path='' as $$ select c.id,c.category,c.location,c.description,c.priority,c.department,c.status,c.resolution,c.photo,c.created_at,case when c.anonymous then 'Anonymous' else coalesce(nullif(p.name,''),'Campus member') end from public.complaints c left join public.profiles p on p.id=c.owner where public.campus_role('admin') or (public.campus_role('provider') and exists(select 1 from public.service_providers s where s.user_id=auth.uid() and s.department=c.department)) order by c.created_at desc $$; revoke all on function public.campus_service_queue() from public; grant execute on function public.campus_service_queue() to authenticated;
create table public.items(id uuid primary key default gen_random_uuid(),owner uuid not null default auth.uid(),title text not null,kind text not null check(kind in ('Lost','Found')),description text not null,location text not null,item_date date not null,photo text not null default '',status text not null default 'Open' check(status in ('Open','Potential Match','Returned','Closed')),created_at timestamptz not null default now());
grant select,insert,update on public.items to authenticated; grant all on public.items to service_role; alter table public.items enable row level security; create policy items_read on public.items for select to authenticated using(true); create policy items_insert on public.items for insert to authenticated with check(owner=(select auth.uid()) and status='Open'); create policy items_edit on public.items for update to authenticated using(owner=(select auth.uid())) with check(owner=(select auth.uid()));
create table public.messages(id uuid primary key default gen_random_uuid(),item_id uuid not null references public.items(id) on delete cascade,sender uuid not null default auth.uid(),recipient uuid not null,body text not null check(length(btrim(body)) between 1 and 4000),created_at timestamptz not null default now(),check(sender<>recipient));
grant select,insert on public.messages to authenticated; grant all on public.messages to service_role; alter table public.messages enable row level security; create policy messages_read on public.messages for select to authenticated using(sender=(select auth.uid()) or recipient=(select auth.uid()));
create function public.campus_has_conversation(item uuid,other uuid) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.messages where item_id=item and sender=other and recipient=auth.uid()) $$; revoke all on function public.campus_has_conversation(uuid,uuid) from public; grant execute on function public.campus_has_conversation(uuid,uuid) to authenticated;
create policy messages_send on public.messages for insert to authenticated with check(sender=(select auth.uid()) and (exists(select 1 from public.items where id=item_id and owner=recipient) or (exists(select 1 from public.items where id=item_id and owner=(select auth.uid())) and public.campus_has_conversation(item_id,recipient))));
create table public.notifications(id uuid primary key default gen_random_uuid(),user_id uuid not null,kind text not null,title text not null,body text not null,read boolean not null default false,created_at timestamptz not null default now());
grant select,update(read) on public.notifications to authenticated; grant all on public.notifications to service_role; alter table public.notifications enable row level security; create policy notifications_own on public.notifications for all to authenticated using(user_id=(select auth.uid())) with check(user_id=(select auth.uid()));
create function public.campus_advance_ticket(ticket uuid,note text) returns text language plpgsql security definer set search_path='' as $$ declare next_status text; ticket_owner uuid; begin update public.complaints c set status=case c.status when 'Submitted' then 'Under Review' when 'Under Review' then 'Assigned' when 'Assigned' then 'In Progress' when 'In Progress' then 'Resolved' end,resolution=left(note,3000) where c.id=ticket and c.status<>'Resolved' and (public.campus_role('admin') or (public.campus_role('provider') and exists(select 1 from public.service_providers s where s.user_id=auth.uid() and s.department=c.department))) returning status,owner into next_status,ticket_owner; if next_status is null then raise exception 'Ticket unavailable'; end if; insert into public.notifications(user_id,kind,title,body) select ticket_owner,'complaint','Campus Care: '||next_status,left(note,3000) where coalesce((select preferences->>'complaint' from public.profiles where id=ticket_owner),'true')='true'; return next_status; end $$; revoke all on function public.campus_advance_ticket(uuid,text) from public; grant execute on function public.campus_advance_ticket(uuid,text) to authenticated;
create function public.campus_message_notice() returns trigger language plpgsql security definer set search_path='' as $$ begin insert into public.notifications(user_id,kind,title,body) select new.recipient,'message','New Lost & Found message','Open Messages to reply.' where coalesce((select preferences->>'message' from public.profiles where id=new.recipient),'true')='true'; return new; end $$; revoke all on function public.campus_message_notice() from public; create trigger campus_message_notice after insert on public.messages for each row execute function public.campus_message_notice();
create policy campus_photo_upload on storage.objects for insert to authenticated with check(bucket_id='campus-media' and (storage.foldername(name))[1]=(select auth.uid())::text);
create policy campus_photo_view on storage.objects for select to authenticated using(bucket_id='campus-media' and ((storage.foldername(name))[1]=(select auth.uid())::text or exists(select 1 from public.items i where i.photo=name and split_part(i.photo,'/',1)=i.owner::text) or exists(select 1 from public.campus_service_queue() q where q.photo=name)));
create function public.campus_insights() returns jsonb language plpgsql stable security definer set search_path='' as $$ begin if not public.campus_role('admin') then raise exception 'Not authorized'; end if; return jsonb_build_object('events',(select count(*) from public.events),'registrations',(select count(*) from public.event_activity where kind='registered'),'complaints',(select count(*) from public.complaints),'resolved',(select count(*) from public.complaints where status='Resolved'),'categories',(select coalesce(jsonb_agg(to_jsonb(x)),'[]') from (select category as name,count(*) as total from public.complaints group by category order by count(*) desc) x),'event_counts',(select coalesce(jsonb_agg(to_jsonb(z)),'[]') from (select e.title as name,count(a.event_id) as total from public.events e left join public.event_activity a on a.event_id=e.id and a.kind='registered' group by e.id order by count(a.event_id) desc limit 20) z)); end $$; revoke all on function public.campus_insights() from public; grant execute on function public.campus_insights() to authenticated;